import {test} from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import os from 'node:os';import path from 'node:path';import {createRequire} from 'node:module';
const require=createRequire(import.meta.url);const {createWelcome}=require('../electron/store-welcome.cjs');
function fixture(t){const dir=fs.mkdtempSync(path.join(os.tmpdir(),'welcome-'));t.after(()=>fs.rmSync(dir,{recursive:true,force:true}));const file=path.join(dir,'store-welcome.json');let now=100000;return {file,make:()=>createWelcome(file,{now:()=>now}),advance:ms=>now+=ms};}
const thread=[{from:'buyer',type:'text',content:'你好',ts:100001}];
test('欢迎每个新顾客只尝试一次，分店隔离且重启不重复',t=>{const f=fixture(t),s=f.make();s.save('a',{text:'甲店欢迎',enabled:true,version:0});f.advance(1);s.observe({storeId:'a',uid:'u',ts:100001});assert.equal(s.claim({storeId:'a',uid:'u',thread}),'甲店欢迎');assert.equal(s.claim({storeId:'a',uid:'u',thread}),'');assert.equal(f.make().claim({storeId:'a',uid:'u',thread}),'');assert.equal(s.claim({storeId:'b',uid:'u',thread}),'');});
test('旧顾客、历史回放和停用都不欢迎，版本冲突保留草稿',t=>{const f=fixture(t),s=f.make();s.seed([{storeId:'a',uid:'old'}]);s.observe({storeId:'a',uid:'before',ts:99990});const saved=s.save('a',{text:'欢迎',enabled:true,version:0});f.advance(2);for(const uid of ['old','before'])assert.equal(s.claim({storeId:'a',uid,thread}),'');s.observe({storeId:'a',uid:'history',ts:100001});assert.equal(s.claim({storeId:'a',uid:'history',thread:[{from:'seller',content:'旧回复',ts:99000},...thread]}),'');s.save('a',{text:saved.text,enabled:false,version:saved.version});assert.throws(()=>s.save('a',{text:saved.text,enabled:saved.enabled,version:saved.version}),/更新/);assert.equal(s.snapshot().a.text,'欢迎');});
test('旧版本草稿迁移默认关闭，坏文件不覆盖',t=>{const f=fixture(t);fs.writeFileSync(f.file,JSON.stringify({version:1,stores:{a:{text:'旧草稿'}}}));const s=f.make();assert.equal(s.snapshot().a.text,'旧草稿');assert.equal(s.snapshot().a.enabled,false);fs.writeFileSync(f.file,'broken');assert.throws(()=>f.make(),/损坏/);assert.equal(fs.readFileSync(f.file,'utf8'),'broken');});
test('欢迎延迟默认1～3秒，随同一条欢迎记录原子保存并支持固定值',t=>{const f=fixture(t),s=f.make();const first=s.save('a',{text:'欢迎',enabled:true,version:0});assert.deepEqual([first.delayMinSeconds,first.delayMaxSeconds],[1,3]);const saved=s.save('a',{text:'欢迎',enabled:true,version:1,delayMinSeconds:5,delayMaxSeconds:9});assert.deepEqual([saved.delayMinSeconds,saved.delayMaxSeconds],[5,9]);assert.equal(saved.version,2);const fixed=s.save('a',{text:'欢迎',enabled:true,version:2,delayMinSeconds:7,delayMaxSeconds:7});assert.deepEqual([fixed.delayMinSeconds,fixed.delayMaxSeconds],[7,7]);assert.equal(f.make().snapshot().a.delayMinSeconds,7);fs.writeFileSync(f.file,JSON.stringify({version:1,stores:{b:{text:'旧草稿'}}}));const migrated=f.make();assert.deepEqual([migrated.snapshot().b.delayMinSeconds,migrated.snapshot().b.delayMaxSeconds],[1,3]);});
test('欢迎延迟拒绝反向、越界和非整数，版本冲突不重写原记录',t=>{const f=fixture(t),s=f.make();const saved=s.save('a',{text:'欢迎',enabled:true,version:0,delayMinSeconds:4,delayMaxSeconds:6});const before=fs.readFileSync(f.file,'utf8');for(const values of [{delayMinSeconds:6,delayMaxSeconds:4},{delayMinSeconds:0,delayMaxSeconds:4},{delayMinSeconds:4,delayMaxSeconds:3601},{delayMinSeconds:4.5,delayMaxSeconds:6},{delayMinSeconds:4,delayMaxSeconds:'6'}])assert.throws(()=>s.save('a',{text:'欢迎',enabled:true,version:saved.version,...values}));assert.throws(()=>s.save('a',{text:'旧',enabled:true,version:0,delayMinSeconds:1,delayMaxSeconds:3}),/更新/);assert.throws(()=>s.save('a',{text:'欢迎',enabled:true,version:saved.version,enabledAt:1}),/Unexpected|unrecognized/i);assert.equal(fs.readFileSync(f.file,'utf8'),before);assert.deepEqual([s.snapshot().a.delayMinSeconds,s.snapshot().a.text],[4,'欢迎']);s.save('a',{text:'欢迎',enabled:true,version:saved.version});assert.deepEqual([s.snapshot().a.delayMinSeconds,s.snapshot().a.delayMaxSeconds],[4,6]);});
test('欢迎延迟损坏的已保存值报错且不改写文件',t=>{const f=fixture(t);const broken={version:2,stores:{a:{text:'欢迎',enabled:true,version:1,enabledAt:100000,delayMinSeconds:9,delayMaxSeconds:2}},seen:[]};fs.writeFileSync(f.file,JSON.stringify(broken));assert.throws(()=>f.make(),/损坏/);assert.equal(fs.readFileSync(f.file,'utf8'),JSON.stringify(broken));});
test('欢迎认领返回实际文字与版本，未认领不产生元数据',t=>{const f=fixture(t),s=f.make();s.save('a',{text:'甲店欢迎',enabled:true,version:0,delayMinSeconds:1,delayMaxSeconds:3});f.advance(1);s.observe({storeId:'a',uid:'u',ts:100001});assert.deepEqual(s.claimEntry({storeId:'a',uid:'u',thread}),{text:'甲店欢迎',version:1});assert.equal(s.claim({storeId:'a',uid:'u',thread}),'');assert.deepEqual(s.claimEntry({storeId:'b',uid:'u',thread}),{text:'',version:0});});

